"""Assemble reports/wu2025_replication.md (tables) from results/wu2025/*.csv. Narrative sections are appended by hand."""
import json, numpy as np, pandas as pd
from pathlib import Path
P = Path(__file__).resolve().parents[1]; R = P / 'results/wu2025'
L = []
def h(s): L.append(f'\n{s}\n')
def tab(df, floatfmt='.3f'): L.append(df.to_markdown(index=False, floatfmt=floatfmt)); L.append('')
h('# Wu et al. (2025) replication of the Collective-ID analyses — tables')
L.append('Generated by `scripts/68_wu_report.py` (2026-10-20). Data: Wu, Deffner, Kahl, Meder, Ho & Kurvers (2025, *Nat Commun* 16:3539), '
         'github.com/charleywu/minecraftforaging — 128 participants, 32 groups of 4, 16 rounds x 120 s (8 solo + 8 group; 4 random + 4 smooth each), 20 Hz positions/heading, Unity visual-field transcription.')
h('## 1. Choice-model fits (per participant MAP; validation against the authors\' Stan posterior means; split-half reliability)')
tab(pd.read_csv(R / 'choice_vs_stan.csv'))
rel = pd.read_csv(R / 'choice_reliability.csv'); tab(rel[rel.split == 'A_vs_B'][['type', 'param', 'r', 'spearman_brown', 'sd_all']])
h('## 2. Reliability of behavioural statistics (split-half r of rounds 1-2 vs 3-4 of each 4-round block, after z-scoring within env; ICC(1) over 8 rounds) and solo-vs-group consistency')
ir = pd.read_csv(R / 'ind_reliability.csv')
w = ir.pivot(index='param', columns='domain', values='r_split')
cols = [c for c in ['stats_solo', 'stats_group', 'solo_vs_group', 'choice_solo', 'choice_group'] if c in w]
w = w[cols].reset_index(); L.append(w.to_markdown(index=False, floatfmt='.2f')); L.append('')
h('## 3. Solo z (PCA of standardised solo movement/foraging statistics): loadings')
ld = pd.read_csv(R / 'z_solo_pca_loadings.csv', index_col=0).drop(columns='expl_var'); L.append(ld.round(2).to_markdown()); L.append('')
h('## 4. Transfer: out-of-fold r (8 folds x 4 sessions) of group-round targets from solo-round sources; noise ceiling = split-half r of the target')
tr = pd.read_csv(R / 'transfer_r.csv'); L.append(tr.to_markdown(index=False, floatfmt='.3f')); L.append('')
h('### 4b. Delta r vs the solo-reward baseline (session-cluster bootstrap, 2000 resamples)')
d = pd.read_csv(R / 'transfer_delta.csv'); tab(d[d.source.isin(['solo_z4', 'solo_z4+choice4'])][['target', 'source', 'r', 'r_ci_lo', 'r_ci_hi', 'delta_r', 'ci_lo', 'ci_hi', 'p_boot', 'noise_ceiling']])
h('## 5. Decomposition of group-round individual outcomes (participant x group round, n = 1024; mixed model: session random intercept + participant variance component; LRT per block)')
tab(pd.read_csv(R / 'decomposition.csv'))
h('## 6. Group-round outcomes (256 group rounds = 32 sessions x 8) predicted from members\' solo measurements (leave-one-session-out ridge; zero-shot nominal = sum of members\' mean solo reward in the same env)')
tab(pd.read_csv(R / 'group_pred.csv'))
h('### 6b. Composition regression (in-sample): mean block vs + SD block, permutation of SD rows within env (2000); and Spearman rho of collective gain with member aggregates')
tab(pd.read_csv(R / 'group_composition.csv'))
for f, title in [('sim_eval.csv', '## 7. Zero-shot ABM simulation of each session x env (authors\' grid ABM, individually fitted 5-weight policies): r within env vs observed (64 cells)'),
                 ('sim_eval_delta.csv', '### 7b. Main vs controls (Delta r, session bootstrap)'), ('sim_shuffle.csv', '### 7c. Membership-shuffle null'), ('sim_calibration.csv', '### 7d. Absolute calibration (mean total reward, simulated vs observed)')]:
    if (R / f).exists():
        h(title); tab(pd.read_csv(R / f))
open(P / 'reports/wu2025_replication_tables.md', 'w').write('\n'.join(L)); print('written')
